def predict(board, action):
    row, col = action
    char = board[row][col]
    if char == 'B':
        board[row][col] = 'S'
        for r in range(max(0, row-1), min(64, row+2)):
            for c in range(max(0, col-1), min(64, col+2)):
                if board[r][c] == 'B':
                    board[r][c] = 'S'
    elif char == 'G':
        board[row][col] = 'p'
    elif char == 'W':
        board[row][col] = 'p'
    else:
        return board
    return ["".join(row) for row in board]
